using Hookline.Modules.Management.Domain.Consumers;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Hookline.Modules.Management.Infrastructure.Configurations;

internal sealed class ConsumerConfiguration : IEntityTypeConfiguration<Consumer>
{
    public void Configure(EntityTypeBuilder<Consumer> builder)
    {
        // Ids are generated by the domain.
        builder.Property(c => c.Id).ValueGeneratedNever();
        builder.Property(c => c.Name).HasMaxLength(Consumer.NameMaxLength);
        builder.Property(c => c.ExternalId).HasMaxLength(Consumer.ExternalIdMaxLength);

        // PostgreSQL does not compare nulls in a unique index, so many consumers can have no external id.
        builder.HasIndex(c => c.ExternalId).IsUnique();
    }
}
